css:
.rtr-wrap { font-family: Arial, sans-serif; font-size: 7.5pt; color: #000; }
.rtr-title { text-align: center; font-size: 13pt; font-weight: bold; margin: 0 0 8px 0; }
.rtr-table { width: 100%; border-collapse: collapse; table-layout: auto; }
.rtr-table th, .rtr-table td { border: 1px solid #000; padding: 4px 6px; vertical-align: middle; font-size: 7.5pt; }
.rtr-table thead tr th, .rtr-table thead tr td { background: #f5f5f5; }
.meta-cell { vertical-align: middle; font-size: 8pt; }
.rotate-cell { width: 60px; min-width: 50px; }
.rotate-text { writing-mode: vertical-rl; transform: rotate(180deg); white-space: nowrap; display: block; min-height: 65px; text-align: left; }
.col-group { font-weight: bold; vertical-align: middle; width: 140px; }
.col-test { width: 120px; }
.col-req { width: 140px; }
.col-val { text-align: center; width: 65px; }
.lbl { font-weight: bold; }

/* meta box (left block without inner borders) */
.meta-box {
  border: 1px solid #000;
  vertical-align: top;
  padding: 6px;
}

.meta-box div {
  border: none;
  margin-bottom: 4px;
}

/* remove default cell border behavior */
.rtr-table .meta-box {
  border: 1px solid #000 !important;
}

/* header logo (added in GrapesJS) */
#rtr-logo { width: 419px; height: 115px; margin: 0 0 6px 0; }

/* footer banner (added in GrapesJS) */
#rtr-footer { display: block; width: 100%; max-width: 100%; height: auto; margin-top: 6px; }
